import React, { useRef } from 'react';
import emailjs from '@emailjs/browser';

function Formulario() {
  const form = useRef();

  const ampliarMensaje = (e) => {
    e.target.style.height = 'auto';
    e.target.style.height = e.target.scrollHeight + 'px';
  };

  const sendEmail = (e) => {
    e.preventDefault();

    emailjs
      .sendForm('service_x26zbd7', 'template_f70jm6p', form.current, {
        publicKey: 'EH-J2WJhCFQLeO',
      })
      .then(
        () => {
          alert('¡Solicitud de adopción/consulta enviada con éxito! Nos pondremos en contacto pronto.');
          form.current.reset();

          const mensaje = form.current.querySelector('textarea');
          mensaje.style.height = '120px';
        },
        (error) => {
          console.log('FAILED...', error.text);
          alert('Error al enviar el formulario. Por favor intenta nuevamente.');
        }
      );
  };

  return (
    <form ref={form} onSubmit={sendEmail} className="form-contacto">
      <h3>Formulario de Adopción y Contacto</h3>

      <div className="form-grupo">
        <label htmlFor="username">Nombre Completo</label>
        <input
          type="text"
          id="username"
          name="username"
          placeholder="Escribe tu nombre completo"
          required
        />
      </div>

      <div className="form-grupo">
        <label htmlFor="email">Correo Electrónico</label>
        <input
          type="email"
          id="email"
          name="email"
          placeholder="ejemplo@correo.com"
          required
        />
      </div>

      <div className="form-grupo">
        <label htmlFor="message">Mascota de Interés / Mensaje</label>
        <textarea
          id="message"
          name="message"
          rows="4"
          placeholder="Indica qué mascota deseas adoptar o escribe tu consulta..."
          onChange={ampliarMensaje}
          required
        />
      </div>

      <input
        type="submit"
        value="Enviar Solicitud"
        className="btn-submit"
      />
    </form>
  );
}

export default Formulario;
